def icon(kind):return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">'+paths.get(kind,paths['note'])+'</svg>'
def head(title,kind='note'):return f'<div class="roothead">{icon(kind)}<h3>{title}</h3><span class="chev">⌃</span></div>'
def card(title,body,kind='note'):return '<div class="rootcard">'+head(title,kind)+body+'</div>'
def button(s,filled=False):return '<div class="button'+(' filled' if filled else '')+'">'+s+'</div>'
def setting(t,sub='',on=None):return '<div class="setting"><div class="row"><strong>'+t+'</strong>'+('' if on is None else '<span class="toggle'+(' on' if on else '')+'"></span>')+'</div><p>'+sub+'</p></div>'
def screen(body,search='Type a command',accent='#e4ff00'):return f'<div class="screen" style="--accent:{accent}"><div class="status"><span>16:42 · Fri, 13 Nov</span><span class="accent">▰ 74%</span></div><div class="content">{body}</div><div class="search">{icon("search")}<span class="grow">{search}</span><span>•••</span></div></div>'
def tile(name,kind,cls='',badge=''):return f'<div class="tile {cls}">{icon(kind)}<span>{name}</span>'+('' if not badge else '<span class="badge">'+badge+'</span>')+'</div>'
forecast='<svg class="chart" viewBox="0 0 350 145"><path d="M10 105L42 92 73 70 105 49 136 35 168 31 199 39 230 56 262 80 294 102 338 110" fill="none" stroke="#f4f5f1" stroke-width="2"/><circle cx="10" cy="105" r="4" fill="#e4ff00"/><g fill="#969c8a" font-size="10"><text x="3" y="140">16:00</text><text x="151" y="140">04:00</text><text x="306" y="140">15:00</text></g></svg>'
