  body='<main class="'+('duo' if len(keys)>1 else '')+'"><div class="copy"><div class="eyebrow">'+eyebrow+'</div><h1>'+html.escape(title)+'</h1><p>'+html.escape(description)+'</p></div>'+phones+'<div class="foot">INTERFACE ILLUSTRATION · SAMPLE CONTENT · NOT A DEVICE CAPTURE</div><div class="brand">Launcher</div></main>'
